1	package numeric
2	
3	import (
4		"fmt"
5		"os"
6		"sync"
7		"sync/atomic"
8		"time"
9	)
10	
11	// Clock 用于注入时间来源，主要服务于确定性测试；生产代码使用墙钟。
12	type Clock interface {
13		Now() time.Time
14	}
15	
16	type wallClock struct{}
17	
18	func (wallClock) Now() time.Time { return time.Now().UTC() }
19	
20	// Option 配置 [Open] 的行为。
21	type Option func(*Store)
22	
23	// WithClock 注入自定义时钟。
24	func WithClock(c Clock) Option {
25		return func(s *Store) { s.now = c.Now }
26	}
27	
28	// Store 是本地数值作业归档：负责提交、调度、取消、查询与持久化。
29	//
30	// 一次只运行一个作业；所有方法可被多个 goroutine 并发调用。
31	type Store struct {
32		dir string
33	
34		mu     sync.Mutex
35		jobs   []*storedJob // 严格按作业号（即提交先后）排列
36		byID   map[uint64]*storedJob
37		idem   map[string]uint64 // submitter\x00requestID -> 作业号
38		nextID uint64
39		closed bool
40	
41		now func() time.Time
42	
43		runningID uint64
44		waitCh    chan struct{}
45		stopCh    chan struct{}
46		stopping  atomic.Bool
47		wg        sync.WaitGroup
48	
49		// compute 仅用于包内确定性测试：若为空则使用真实的 [computeResult]。
50		// 必须在任何 Submit 之前（Open 之后立即）设置；worker 只会在收到
51		// Submit 的唤醒之后读取它，因此与设置之间存在 happens-before 关系。
52		compute func(id uint64, inputs []int64, seed int64, canceled func() bool) (sum, sumSquares int64, reason string, ok bool)
53	}
54	
55	// Open 打开（必要时创建）目录 dir 并恢复其中的全部作业记录。
56	//
57	// 恢复语义：
58	//   - 已确认的提交、取消与完成结果原样保留，幂等请求号继续生效；
59	//   - 上次关闭时仍在运行的作业标记为失败（计算被中断）并阻止其下游；
60	//   - 排队作业继续排队并由本地唯一 worker 按提交先后处理；
61	//   - 成功状态始终与完整归档同时可见。
62	func Open(dir string, opts ...Option) (*Store, error) {
63		if err := os.MkdirAll(dir, 0o700); err != nil {
64			return nil, err
65		}
66		jobs, maxID, err := loadDir(dir)
67		if err != nil {
68			return nil, err
69		}
70		s := &Store{
71			dir:    dir,
72			jobs:   jobs,
73			byID:   make(map[uint64]*storedJob),
74			idem:   make(map[string]uint64),
75			nextID: maxID + 1,
76			now:    wallClock{}.Now,
77			waitCh: make(chan struct{}, 1),
78			stopCh: make(chan struct{}),
79		}
80		for _, opt := range opts {
81			opt(s)
82		}
83		for _, j := range jobs {
84			s.byID[j.id] = j
85			if j.requestID != "" {
86				s.idem[s.idemKey(j.submitter, j.requestID)] = j.id
87			}
88		}
89		// 重建失败/取消作业对排队下游的阻断。
90		s.cascadeLocked()
91		s.wg.Add(1)
92		go s.worker()
93		return s, nil
94	}
95	
96	func (s *Store) idemKey(submitter, requestID string) string {
97		return submitter + "\x00" + requestID
98	}
99	
100	// Close 关闭归档。正在运行的作业会尽快中止并标记为失败（计算被中断），
101	// 排队作业原样保留在磁盘上，下次 [Open] 继续。
102	func (s *Store) Close() error {
103		s.mu.Lock()
104		if s.closed {
105			s.mu.Unlock()
106			return nil
107		}
108		s.closed = true
109		var running *storedJob
110		if s.runningID != 0 {
111			running = s.byID[s.runningID]
112		}
113		s.mu.Unlock()
114	
115		if s.stopping.CompareAndSwap(false, true) {
116			close(s.stopCh)
117		}
118		// 中止正在运行的计算。
119		if running != nil {
120			running.canceled.Store(true)
121		}
122		s.notify()
123		s.wg.Wait()
124		return nil
125	}
126	
127	// Submit 接受一次作业提交。
128	//
129	// 空序列返回 [ErrEmptySequence]；引用不存在的依赖返回
130	// [ErrDependencyNotFound]；同一提交人复用请求号但内容变化返回
131	// [ErrIdempotencyConflict]（同时返回原作业视图）——这些拒绝都不产生记录。
132	// 相同提交人+请求号+内容的重复提交（含并发重复）返回原作业及其当前状态。
133	func (s *Store) Submit(req SubmitRequest) (*Job, error) {
134		s.mu.Lock()
135		defer s.mu.Unlock()
136		if s.closed || s.stopping.Load() {
137			return nil, ErrStoreClosed
138		}
139		if len(req.Values) == 0 {
140			return nil, ErrEmptySequence
141		}
142		if err := s.validateDependenciesLocked(&req); err != nil {
143			return nil, err
144		}
145		deps := requestDeps(&req)
146		if req.RequestID != "" {
147			key := s.idemKey(req.Submitter, req.RequestID)
148			if origID, ok := s.idem[key]; ok {
149				orig := s.byID[origID]
150				if sameContent(orig, &req) {
151					return s.viewLocked(orig), nil
152				}
153				return s.viewLocked(orig),
154					fmt.Errorf("%w：提交人 %q 的请求号 %q 已用于作业 %d",
155						ErrIdempotencyConflict, req.Submitter, req.RequestID, origID)
156			}
157		}
158	
159		now := s.now().UTC()
160		j := &storedJob{
161			id:           s.nextID,
162			submitter:    req.Submitter,
163			requestID:    req.RequestID,
164			seed:         req.Seed,
165			values:       append([]int64(nil), req.Values...),
166			dependencies: append([]uint64(nil), deps...),
167			queuedAt:     now,
168			status:       StatusQueued,
169		}
170		// 先持久化，接受之后该提交即不可丢失。
171		if err := s.persist(j); err != nil {
172			return nil, err
173		}
174		s.nextID++
175		s.jobs = append(s.jobs, j)
176		s.byID[j.id] = j
177		if req.RequestID != "" {
178			s.idem[s.idemKey(req.Submitter, req.RequestID)] = j.id
179		}
180		// 依赖已失败/取消时，新接受的作业立刻进入失败终态。
181		s.cascadeLocked()
182		s.notifyLocked()
183		return s.viewLocked(j), nil
184	}
185	
186	// requestDeps 规范化一次提交的直接上游作业号列表：
187	// 非空 Dependencies 优先（保持次序）；否则单依赖方式退化为只含一个作业号的列表；
188	// 两者皆无则为 nil。调用前须先经 [Store.validateDependenciesLocked] 校验。
189	func requestDeps(req *SubmitRequest) []uint64 {
190		if len(req.Dependencies) > 0 {
191			return append([]uint64(nil), req.Dependencies...)
192		}
193		if req.HasDependency {
194			return []uint64{req.DependencyID}
195		}
196		return nil
197	}
198	
199	// validateDependenciesLocked 在持锁状态下校验提交的依赖列表：
200	//   - 单依赖方式与非空列表同时启用 → 拒绝；
201	//   - 列表含零或重复作业号 → 拒绝（错误指出具体作业号）；
202	//   - 列表引用提交时不存在的作业 → 拒绝。
203	//
204	// 任一拒绝都不产生记录，也不占用幂等请求号。
205	func (s *Store) validateDependenciesLocked(req *SubmitRequest) error {
206		if req.HasDependency && len(req.Dependencies) > 0 {
207			return fmt.Errorf("%w：单依赖方式与依赖列表不能同时启用", ErrInvalidDependency)
208		}
209		deps := requestDeps(req)
210		seen := make(map[uint64]struct{}, len(deps))
211		for _, id := range deps {
212			if id == 0 {
213				return fmt.Errorf("%w：依赖列表包含无效作业号 0", ErrInvalidDependency)
214			}
215			if _, dup := seen[id]; dup {
216				return fmt.Errorf("%w：依赖列表包含重复作业号 %d", ErrInvalidDependency, id)
217			}
218			seen[id] = struct{}{}
219		}
220		for _, id := range deps {
221			if s.byID[id] == nil {
222				return fmt.Errorf("%w：作业号 %d", ErrDependencyNotFound, id)
223			}
224		}
225		return nil
226	}
227	
228	// sameContent 判断两次提交的内容是否一致；整数次序或依赖列表（内容与次序）
229	// 不同即视为不同内容。单依赖方式与只含同一作业号的列表视为相同内容。
230	func sameContent(j *storedJob, req *SubmitRequest) bool {
231		if j.seed != req.Seed {
232			return false
233		}
234		rd := requestDeps(req)
235		if len(j.dependencies) != len(rd) {
236			return false
237		}
238		for i := range j.dependencies {
239			if j.dependencies[i] != rd[i] {
240				return false
241			}
242		}
243		if len(j.values) != len(req.Values) {
244			return false
245		}
246		for i := range j.values {
247			if j.values[i] != req.Values[i] {
248				return false
249			}
250		}
251		return true
252	}
253	
254	// Get 按作业号读取作业详情（含成功归档）；不存在返回 [ErrNotFound]。
255	func (s *Store) Get(id uint64) (*Job, error) {
256		s.mu.Lock()
257		defer s.mu.Unlock()
258		j := s.byID[id]
259		if j == nil {
260			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
261		}
262		return s.viewLocked(j), nil
263	}
264	
265	// Cancel 请求取消作业。
266	//
267	// 排队或运行中的作业都可以取消；取消以“取消状态已成功保存进归档记录”为生效
268	// 条件：只有原子替换原记录成功后，返回结果、可查询状态与磁盘记录才一致地呈现
269	// 为取消，该作业及依赖它的作业才不会再产生成功归档。若取消记录无法创建临时
270	// 文件或无法替换原记录，返回的是实际保存错误，作业保持原状——不新增完成时间、
271	// 不清空原有信息、不中止正在运行的计算、不级联标记下游，排队与调度规则不变；
272	// 写入条件恢复后对仍处于排队或运行状态的同一作业再次取消会重新尝试保存。
273	// 重复取消已取消的作业仍返回成功；对已成功或已失败的作业取消返回
274	// [ErrNotCancellable]，原结果保持不变（计算在两次取消请求之间完成时亦然）。
275	func (s *Store) Cancel(id uint64) (*Job, error) {
276		s.mu.Lock()
277		defer s.mu.Unlock()
278		if s.closed {
279			return nil, ErrStoreClosed
280		}
281		j := s.byID[id]
282		if j == nil {
283			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
284		}
285		switch j.status {
286		case StatusCanceled:
287			return s.viewLocked(j), nil
288		case StatusSucceeded, StatusFailed:
289			return s.viewLocked(j),
290				fmt.Errorf("%w：作业 %d 当前状态为 %s", ErrNotCancellable, id, j.status)
291		}
292	
293		// queued / running：先把取消终态写入原记录，确认原子替换成功后才让取消
294		// 生效。持锁期间外界观察不到中间态；若创建临时记录或替换原记录失败，
295		// 必须逐字段回滚，内存与磁盘都保持取消前的原状并返回实际保存错误，
296		// 不能把这次取消当作已完成。
297		now := s.now().UTC()
298		prevStatus := j.status
299		prevFinishedAt := j.finishedAt
300		prevReason := j.failureReason
301		prevBlocker := j.blockerID
302		prevEffective := j.effectiveValues
303		prevArchive := j.archive
304		j.status = StatusCanceled
305		j.failureReason = ""
306		j.blockerID = 0
307		if j.finishedAt.IsZero() {
308			j.finishedAt = now
309		}
310		j.effectiveValues = nil
311		j.archive = nil
312		if err := s.persist(j); err != nil {
313			j.status = prevStatus
314			j.finishedAt = prevFinishedAt
315			j.failureReason = prevReason
316			j.blockerID = prevBlocker
317			j.effectiveValues = prevEffective
318			j.archive = prevArchive
319			return nil, err
320		}
321	
322		// 取消已确认保存：提交终态，让正在运行的计算尽快中止，并级联标记下游。
323		j.canceled.Store(true)
324		// 依赖它的等待者一并失败，且继续向更下游传播。
325		s.cascadeLocked()
326		s.notifyLocked()
327		return s.viewLocked(j), nil
328	}
329	
330	// List 按提交人和提交时间范围（两端均包含）列出记录，结果按提交先后排列。
331	// start 晚于 end 返回 [ErrInvalidTimeRange]。零值时间表示该端不限。
332	func (s *Store) List(submitter string, start, end time.Time) ([]*Job, error) {
333		s.mu.Lock()
334		defer s.mu.Unlock()
335		if !start.IsZero() && !end.IsZero() && start.After(end) {
336			return nil, fmt.Errorf("%w：起始时间 %s 晚于结束时间 %s",
337				ErrInvalidTimeRange, start.Format(time.RFC3339Nano), end.Format(time.RFC3339Nano))
338		}
339		out := make([]*Job, 0)
340		for _, j := range s.jobs { // jobs 已按 id 升序，即提交先后
341			if j.submitter != submitter {
342				continue
343			}
344			if !start.IsZero() && j.queuedAt.Before(start) {
345				continue
346			}
347			if !end.IsZero() && j.queuedAt.After(end) {
348				continue
349			}
350			out = append(out, s.viewLocked(j))
351		}
352		return out, nil
353	}
354	
355	// cascadeLocked 把“直接上游已失败/取消”的排队作业标记为失败并递归传播。
356	//
357	// 上游在提交时必须已存在，因此上游作业号必然更小，按作业号升序单趟
358	// 扫描即可让阻断沿链条传播到最下游。作业有多个直接上游时，按列表顺序
359	// 选取最靠前的已失败/取消者作为直接阻断者；作业一旦失败，其原因不再被
360	// 后来发生的上游状态变化改写。
361	func (s *Store) cascadeLocked() {
362		for _, j := range s.jobs {
363			if j.status != StatusQueued || len(j.dependencies) == 0 {
364				continue
365			}
366			var direct *storedJob
367			for _, id := range j.dependencies {
368				dep := s.byID[id]
369				if dep == nil {
370					continue
371				}
372				if dep.status == StatusFailed || dep.status == StatusCanceled {
373					direct = dep
374					break
375				}
376			}
377			if direct == nil {
378				continue
379			}
380			root := direct.blockerID
381			if root == 0 {
382				root = direct.id
383			}
384			s.markFailedLocked(j, blockedReason(direct, root), root)
385		}
386	}
387	
388	func blockedReason(dep *storedJob, root uint64) string {
389		state := "失败"
390		if dep.status == StatusCanceled {
391			state = "被取消"
392		}
393		reason := fmt.Sprintf("直接上游作业 %d 已%s，阻断本作业继续计算", dep.id, state)
394		if dep.status == StatusFailed && dep.failureReason != "" {
395			reason += "（其失败原因：" + dep.failureReason + "）"
396		}
397		if root != dep.id {
398			reason += fmt.Sprintf("；阻断根因为作业 %d", root)
399		}
400		return reason
401	}
402	
403	// pickRunnableLocked 返回提交顺序上第一个可运行的排队作业。
404	// 可运行要求全部直接上游都已成功并归档；只要还有一个上游在排队或运行，
405	// 该作业就被跳过，不挡住后面可运行的作业。
406	func (s *Store) pickRunnableLocked() *storedJob {
407		for _, j := range s.jobs {
408			if j.status != StatusQueued {
409				continue
410			}
411			if len(j.dependencies) == 0 {
412				return j
413			}
414			ready := true
415			for _, id := range j.dependencies {
416				dep := s.byID[id]
417				if dep == nil || dep.status != StatusSucceeded {
418					ready = false
419					break
420				}
421			}
422			if ready {
423				return j
424			}
425		}
426		return nil
427	}
428	
429	// notifyLocked 在持锁状态下非阻塞唤醒 worker。
430	func (s *Store) notifyLocked() {
431		select {
432		case s.waitCh <- struct{}{}:
433		default:
434		}
435	}
436	
437	// notify 在不持锁时唤醒 worker。
438	func (s *Store) notify() {
439		s.mu.Lock()
440		s.notifyLocked()
441		s.mu.Unlock()
442	}
443	
444	// persistRetry 对落盘做有限次重试，尽量避免内存状态与磁盘记录分叉。
445	func (s *Store) persistRetry(j *storedJob, attempts int) error {
446		var err error
447		for i := 0; i < attempts; i++ {
448			if err = s.persist(j); err == nil {
449				return nil
450			}
451		}
452		return err
453	}
454	
455	// worker 是本地唯一的计算执行体。
456	func (s *Store) worker() {
457		defer s.wg.Done()
458		for {
459			s.mu.Lock()
460			if s.stopping.Load() {
461				s.mu.Unlock()
462				return
463			}
464			j := s.pickRunnableLocked()
465			if j == nil {
466				ch := s.waitCh
467				s.mu.Unlock()
468				select {
469				case <-ch:
470				case <-s.stopCh:
471				}
472				continue
473			}
474	
475			// 进入运行并原子持久化该状态。
476			j.status = StatusRunning
477			j.startedAt = s.now().UTC()
478			// 实际输入 = 原始序列 + 各直接上游的总和（严格按列表顺序追加）。
479			inputs := append([]int64(nil), j.values...)
480			for _, id := range j.dependencies {
481				if dep := s.byID[id]; dep != nil && dep.archive != nil {
482					inputs = append(inputs, dep.archive.Sum)
483				}
484			}
485			seed := j.seed
486			s.runningID = j.id
487			if err := s.persistRetry(j, 3); err != nil {
488				// 连运行状态都无法落盘：保守地失败，不进行计算。
489				s.markFailedLocked(j, "无法持久化作业状态："+err.Error(), 0)
490				s.runningID = 0
491				s.cascadeLocked()
492				s.notifyLocked()
493				s.mu.Unlock()
494				continue
495			}
496			s.mu.Unlock()
497	
498			abort := func() bool { return j.canceled.Load() || s.stopping.Load() }
499			doCompute := s.compute
500			if doCompute == nil {
501				doCompute = func(_ uint64, in []int64, sd int64, c func() bool) (int64, int64, string, bool) {
502					return computeResult(in, sd, c)
503				}
504			}
505			sum, sumSq, reason, ok := doCompute(j.id, inputs, seed, abort)
506	
507			s.mu.Lock()
508			s.runningID = 0
509			switch {
510			case j.status == StatusCanceled:
511				// 用户取消已在 Cancel 中落盘；此处确保丢弃任何计算产物。
512				j.archive = nil
513				j.effectiveValues = nil
514				_ = s.persistRetry(j, 3)
515				s.cascadeLocked()
516			case s.stopping.Load():
517				s.markFailedLocked(j, "计算被中断：归档在计算过程中关闭", 0)
518				s.cascadeLocked()
519			case !ok:
520				s.markFailedLocked(j, reason, 0)
521				s.cascadeLocked()
522			default:
523				// 成功：状态与完整归档在同一条记录的同一次原子写入中可见。
524				completed := s.now().UTC()
525				a := newArchive(j, inputs, sum, sumSq, completed)
526				j.effectiveValues = append([]int64(nil), inputs...)
527				j.status = StatusSucceeded
528				j.finishedAt = completed
529				j.failureReason = ""
530				j.blockerID = 0
531				j.archive = a
532				if err := s.persistRetry(j, 3); err != nil {
533					// 落盘失败时绝不让对外可见“成功却没有归档”：回退为失败。
534					j.archive = nil
535					j.effectiveValues = nil
536					s.markFailedLocked(j, "结果归档写入失败："+err.Error(), 0)
537				}
538			}
539			s.notifyLocked()
540			s.mu.Unlock()
541		}
542	}
543	
544	// markFailedLocked 在持锁状态下把作业置为失败终态并尝试落盘。
545	func (s *Store) markFailedLocked(j *storedJob, reason string, blocker uint64) {
546		j.status = StatusFailed
547		j.failureReason = reason
548		j.blockerID = blocker
549		if j.finishedAt.IsZero() {
550			j.finishedAt = s.now().UTC()
551		}
552		j.archive = nil
553		j.effectiveValues = nil
554		_ = s.persistRetry(j, 3)
555	}
556	
557	// newArchive 构造成功归档；CompletedAt 之外的全部字段都是确定性的。
558	// 上游作业号只作记录，不参与任何摘要与校验值。
559	func newArchive(j *storedJob, effective []int64, sum, sumSquares int64, completedAt time.Time) *Archive {
560		inDigest := inputsDigestHex(effective, j.seed)
561		resDigest := resultDigestHex(effective, j.seed, sum, sumSquares)
562		log := buildLog(effective, j.seed, sum, sumSquares)
563		checksum := checksumHex(effective, j.seed, sum, sumSquares, log, resDigest)
564		var firstDep uint64
565		if len(j.dependencies) > 0 {
566			firstDep = j.dependencies[0]
567		}
568		return &Archive{
569			JobID:           j.id,
570			Submitter:       j.submitter,
571			RequestID:       j.requestID,
572			Seed:            j.seed,
573			Values:          append([]int64(nil), j.values...),
574			HasDependency:   len(j.dependencies) > 0,
575			DependencyID:    firstDep,
576			Dependencies:    append([]uint64(nil), j.dependencies...),
577			EffectiveValues: append([]int64(nil), effective...),
578			InputsDigest:    inDigest,
579			Sum:             sum,
580			SumOfSquares:    sumSquares,
581			ResultDigest:    resDigest,
582			Log:             log,
583			Checksum:        checksum,
584			CompletedAt:     completedAt,
585		}
586	}
587	
588	// viewLocked 在持锁状态下生成对外只读视图，全部切片深拷贝。
589	func (s *Store) viewLocked(j *storedJob) *Job {
590		v := &Job{
591			ID:              j.id,
592			Submitter:       j.submitter,
593			RequestID:       j.requestID,
594			Seed:            j.seed,
595			Values:          append([]int64(nil), j.values...),
596			Dependencies:    append([]uint64(nil), j.dependencies...),
597			QueuedAt:        j.queuedAt,
598			StartedAt:       j.startedAt,
599			FinishedAt:      j.finishedAt,
600			Status:          j.status,
601			FailureReason:   j.failureReason,
602			BlockerID:       j.blockerID,
603			EffectiveValues: append([]int64(nil), j.effectiveValues...),
604		}
605		v.HasDependency = len(j.dependencies) > 0
606		if len(j.dependencies) > 0 {
607			v.DependencyID = j.dependencies[0]
608		}
609		if j.status == StatusQueued {
610			v.WaitReason = WaitSlot
611			// 列出尚未成功归档的直接上游，保持提交时的顺序。
612			for _, id := range j.dependencies {
613				if dep := s.byID[id]; dep == nil || dep.status != StatusSucceeded {
614					v.PendingDependencies = append(v.PendingDependencies, id)
615				}
616			}
617			if len(v.PendingDependencies) > 0 {
618				v.WaitReason = WaitDependency
619			}
620		}
621		if j.archive != nil {
622			a := *j.archive
623			a.Values = append([]int64(nil), j.archive.Values...)
624			a.EffectiveValues = append([]int64(nil), j.archive.EffectiveValues...)
625			a.Dependencies = append([]uint64(nil), j.archive.Dependencies...)
626			v.Archive = &a
627		}
628		return v
629	}
630	
631	// Dir 返回归档目录路径。
632	func (s *Store) Dir() string { return s.dir }
633

