110		return j.dependencies[0]
111	}
112	
113	// persist 在已持锁的情况下原子写一条作业记录。
114	func (s *Store) persist(j *storedJob) error {
115		data, err := encodeRecord(j)
116		if err != nil {
117			return err
118		}
119		return writeFileAtomic(s.dir, jobFileName(j.id), data, 0o600)
120	}
121	
122	// writeFileAtomic 将 data 写入 dir/name：同目录临时文件 → fsync → rename
123	// → 目录 fsync，保证记录要么是旧内容要么是新内容，不会出现半条记录。
124	func writeFileAtomic(dir, name string, data []byte, perm os.FileMode) error {
125		tmp, err := os.CreateTemp(dir, ".tmp-"+name+".*")
126		if err != nil {
127			return err
128		}
129		tmpName := tmp.Name()
130		cleanup := true
131		defer func() {
132			if cleanup {
133				_ = os.Remove(tmpName)
134			}
135		}()
136	
137		if _, err := tmp.Write(data); err != nil {
138			_ = tmp.Close()
139			return err
140		}
141		if err := tmp.Sync(); err != nil {
142			_ = tmp.Close()
143			return err
144		}
145		if err := tmp.Close(); err != nil {
146			return err
147		}
148		if err := os.Chmod(tmpName, perm); err != nil {
149			return err
150		}
151		if err := os.Rename(tmpName, filepath.Join(dir, name)); err != nil {
152			return err
153		}
154		cleanup = false
155		syncDir(dir)
156		return nil
157	}
158	
159	// syncDir 对目录本身做一次 fsync，让新建项与 rename 在崩溃后仍然成立。
160	func syncDir(dir string) {
161		if d, err := os.Open(dir); err == nil {
162			_ = d.Sync()
163			_ = d.Close()
164		}
165	}
166	
167	// loadDir 扫描目录中的全部作业记录并重建内存索引。
168	//
169	// 恢复规则：
170	//   - 上次关闭时仍为 running 的作业标记为失败，原因是计算被中断；
171	//   - 成功记录缺少归档或校验值对不上时 fail-closed 地标记为失败，
172	//     维持“成功必有完整归档”的不变量。
173	func loadDir(dir string) ([]*storedJob, uint64, error) {
174		entries, err := os.ReadDir(dir)
175		if err != nil {
176			return nil, 0, err
177		}
178		var jobs []*storedJob
179		var maxID uint64
180		for _, e := range entries {
181			name := e.Name()
182			if e.IsDir() {
183				continue
184			}
185			// 清理上一进程崩溃时可能残留的原子写临时文件。
186			if strings.HasPrefix(name, ".tmp-") {
187				_ = os.Remove(filepath.Join(dir, name))
188				continue
189			}
190			if !strings.HasPrefix(name, "job-") || !strings.HasSuffix(name, ".json") {
191				continue
192			}
193			path := filepath.Join(dir, name)
194			data, err := os.ReadFile(path)
195			if err != nil {
196				return nil, 0, err
197			}
198			var r jobRecord
199			if err := json.Unmarshal(data, &r); err != nil {
200				return nil, 0, fmt.Errorf("numeric: 记录 %s 损坏: %w", name, err)
201			}
202			if r.Version != recordVersion {
203				return nil, 0, fmt.Errorf("numeric: 记录 %s 版本不受支持: %s", name, r.Version)
204			}
205			switch r.Status {
206			case StatusQueued, StatusRunning, StatusSucceeded, StatusFailed, StatusCanceled:
207			default:
208				return nil, 0, fmt.Errorf("numeric: 记录 %s 状态非法: %q", name, r.Status)
209			}
210			// 新格式记录直接给出有序依赖列表；旧格式记录只有单依赖字段，
211			// 恢复为只含一个作业号的列表（语义与提交时一致）。
212			deps := append([]uint64(nil), r.Dependencies...)
213			if len(deps) == 0 && r.HasDependency {
214				deps = []uint64{r.DependencyID}
215			}
216			j := &storedJob{
217				id:           r.ID,
218				submitter:    r.Submitter,
219				requestID:    r.RequestID,
220				seed:         r.Seed,
221				values:       append([]int64(nil), r.Values...),
222				dependencies: deps,
223	
224				queuedAt:   r.QueuedAt,
225				startedAt:  r.StartedAt,
226				finishedAt: r.FinishedAt,
227	
228				status:        r.Status,
229				failureReason: r.FailureReason,
230				blockerID:     r.BlockerID,
231	
232				effectiveValues: append([]int64(nil), r.EffectiveValues...),
233				archive:         r.Archive,
234			}
235			if j.status == StatusRunning {
236				j.status = StatusFailed
237				j.failureReason = "计算被中断：归档上次关闭时作业仍在运行"
238				j.blockerID = 0
239				if j.finishedAt.IsZero() {
240					j.finishedAt = time.Now().UTC()
241				}
242				j.effectiveValues = nil
243				j.archive = nil
244				// 就地重写恢复后的终态。
245				if data, err := encodeRecord(j); err == nil {
246					_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
247				}
248			}
249			if j.status == StatusSucceeded && !archiveIntact(j) {
250				j.status = StatusFailed
251				j.failureReason = "归档不完整或校验值不一致，成功结果不可用"
252				if j.finishedAt.IsZero() {
253					j.finishedAt = time.Now().UTC()
254				}
255				j.effectiveValues = nil
256				j.archive = nil
257				if data, err := encodeRecord(j); err == nil {
258					_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
259				}
260			}
261			jobs = append(jobs, j)
262			if j.id > maxID {
263				maxID = j.id
264			}
265		}
266		// 恢复后的排列必须与关闭前的接受先后一致：作业号在接受时单调分配，
267		// 按作业号升序即提交先后。记录上的提交时间只用于时间范围过滤，
268		// 不参与排序——本机时钟回拨会让后接受的作业带有更早的时间，
269		// 按时间重排会改变已确定的先后关系（也会让上游作业号更大的
270		// 依赖链在单趟级联扫描中漏掉失败传播）。
271		sort.Slice(jobs, func(a, b int) bool {
272			return jobs[a].id < jobs[b].id
273		})
274		return jobs, maxID, nil
275	}
276	
277	// archiveIntact 复算成功归档的全部确定性字段，任何不一致都视为不可用。
278	func archiveIntact(j *storedJob) bool {
279		a := j.archive
280		if a == nil {
281			return false
282		}
283		// 归档中的原始参数必须与记录顶层字段一致。
284		if a.JobID != j.id || a.Submitter != j.submitter || a.RequestID != j.requestID ||
285			a.Seed != j.seed || a.HasDependency != (len(j.dependencies) > 0) {
286			return false
287		}
288		if a.HasDependency && a.DependencyID != depID(j) {
289			return false
290		}
291		// 依赖列表（内容与次序）必须一致。旧格式归档没有 dependencies 字段，
292		// 由单依赖字段推导后再比较。
293		aDeps := append([]uint64(nil), a.Dependencies...)
294		if len(aDeps) == 0 && a.HasDependency {
295			aDeps = []uint64{a.DependencyID}
296		}
297		if len(aDeps) != len(j.dependencies) {
298			return false
299		}
300		for i := range j.dependencies {
301			if aDeps[i] != j.dependencies[i] {
302				return false
303			}
304		}
305		if len(a.Values) != len(j.values) {
306			return false
307		}
308		for i := range j.values {
309			if a.Values[i] != j.values[i] {
310				return false
311			}
312		}
313		if len(j.effectiveValues) == 0 || len(a.EffectiveValues) != len(j.effectiveValues) {
314			return false
315		}
316		for i := range j.effectiveValues {
317			if j.effectiveValues[i] != a.EffectiveValues[i] {
318				return false
319			}
320		}
321		if a.InputsDigest != inputsDigestHex(j.effectiveValues, j.seed) {
322			return false
323		}
324		if a.ResultDigest != resultDigestHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
325			return false
326		}
327		if a.Log != buildLog(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
328			return false
329		}
330		if a.Checksum != checksumHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares, a.Log, a.ResultDigest) {
331			return false
332		}
333		return true
334	}
