233		if g, _ := s.Get(q.ID); g.Status != StatusQueued {
234			t.Fatalf("job must remain queued after failed cancel: %s", g.Status)
235		}
236	
237		release(head.ID)
238		done := waitStatus(t, s, q.ID, StatusSucceeded)
239		if done.Archive.Sum != 5 {
240			t.Fatalf("queued job must still run normally, sum=%d", done.Archive.Sum)
241		}
242	}
243	
244	// 取消成功保存后，正在运行的计算即使随后“成功完成”也不能留下成功归档；
245	// 关闭重开归档后，已确认的取消仍然成立。
246	func TestConfirmedRunningCancelDiscardsLateSuccess(t *testing.T) {
247		dir := t.TempDir()
248		s, err := Open(dir)
249		if err != nil {
250			t.Fatal(err)
251		}
252		// 自定义钩子：放行后无视取消信号、照常返回成功结果，模拟计算在取消确认
253		// 之后才结束的竞态。
254		started := make(chan uint64, 1)
255		gate := make(chan struct{})
256		s.compute = func(_ uint64, _ []int64, _ int64, _ func() bool) (int64, int64, string, bool) {
257			started <- 1
258			<-gate
259			return 3, 5, "", true
260		}
261		run := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1, 2}})
262		waitStarted(t, started, run.ID)
263	
264		cj, err := s.Cancel(run.ID)
265		if err != nil || cj.Status != StatusCanceled {
266			t.Fatalf("cancel running: %+v %v", cj, err)
267		}
268		if g, _ := s.Get(run.ID); g.Status != StatusCanceled || g.FinishedAt.IsZero() {
269			t.Fatalf("query right after confirmed cancel: %+v", g)
270		}
271		close(gate) // 计算随即以“成功”返回；其产物必须被丢弃。
272	
273		// Close 会等待 worker 走完计算后的裁决分支，返回即说明晚到的成功结果
274		// 已被处理，磁盘上必须仍是取消记录且不含归档。
275		if err := s.Close(); err != nil {
276			t.Fatal(err)
277		}
278		data, err := os.ReadFile(filepath.Join(dir, jobFileName(run.ID)))
279		if err != nil {
280			t.Fatal(err)
281		}
282		if !strings.Contains(string(data), `"status": "canceled"`) ||
283			strings.Contains(string(data), `"archive"`) {
284			t.Fatalf("late compute success must not be archived:\n%s", data)
285		}
286	
287		s2, err := Open(dir)
288		if err != nil {
289			t.Fatal(err)
290		}
291		defer s2.Close()
