622		second := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{2}})
623		if j, _ := s.Get(second.ID); j.WaitReason != WaitSlot {
624			t.Fatalf("reason=%q want WaitSlot", j.WaitReason)
625		}
626		if _, err := s.Cancel(second.ID); err != nil {
627			t.Fatalf("cancel queued: %v", err)
628		}
629		release(first.ID)
630		waitStatus(t, s, first.ID, StatusSucceeded)
631		j, _ := s.Get(second.ID)
632		if j.Status != StatusCanceled || j.Archive != nil {
633			t.Fatalf("queued cancel: status=%s archive=%v", j.Status, j.Archive)
634		}
